{
  "iteration": 1,
  "pcvs": [
    {
      "name": "request_count_proxy",
      "expression": "int(use_tqdm) + 1",
      "rationale": "The supplied workload sets use_tqdm to batch size minus one, providing a cheap proxy for per-request work."
    },
    {
      "name": "decode_rounds_proxy",
      "expression": "2 * int(use_tqdm) + 1 if use_tqdm < 2 else 4",
      "rationale": "Matches each batch's maximum requested generation length, approximating engine-step overhead."
    },
    {
      "name": "long_prompt_requests",
      "expression": "int(use_tqdm) + 1 if use_tqdm >= 4 else 0",
      "rationale": "Measures batch size for the long shared-prefix prompt regime."
    },
    {
      "name": "initial_batch",
      "expression": "int(use_tqdm == 0)",
      "rationale": "Identifies initial execution overhead and the batch without progress reporting."
    }
  ],
  "hypothesis": "Per-request work, decoding rounds, long-prompt processing, and initial-execution overhead explain instruction counts using cheap workload-specific entry-state proxies."
}
